#include <cstdio>
#include <cstdlib>
#include <vector>
#include <thread>
#include <atomic>
#include <string>
#include <algorithm>

struct Node {
    Node* left;
    Node* right;
};

struct Arena {
    std::vector<Node> buf;
    size_t idx = 0;
    explicit Arena(size_t n) : buf(n) {}
    inline Node* alloc() { return &buf[idx++]; }
    inline void reset() { idx = 0; }
};

static Node* make(int depth, Arena& a) {
    Node* n = a.alloc();
    if (depth > 0) {
        n->left = make(depth - 1, a);
        n->right = make(depth - 1, a);
    } else {
        n->left = nullptr;
        n->right = nullptr;
    }
    return n;
}

static long check(const Node* n) {
    if (n->left == nullptr) return 1;
    return 1 + check(n->left) + check(n->right);
}

int main(int argc, char** argv) {
    int n = (argc > 1) ? std::atoi(argv[1]) : 10;
    const int minDepth = 4;
    int maxDepth = std::max(minDepth + 2, n);
    int stretchDepth = maxDepth + 1;

    {
        Arena a((size_t(1) << (stretchDepth + 1)) - 1);
        Node* stretch = make(stretchDepth, a);
        std::printf("stretch tree of depth %d\t check: %ld\n", stretchDepth, check(stretch));
    }

    Arena longArena((size_t(1) << (maxDepth + 1)) - 1);
    Node* longLived = make(maxDepth, longArena);

    int numDepths = (maxDepth - minDepth) / 2 + 1;
    std::vector<std::string> results(numDepths);
    std::atomic<int> next(0);

    auto worker = [&]() {
        for (;;) {
            int i = next.fetch_add(1);
            if (i >= numDepths) break;
            int depth = minDepth + 2 * i;
            long iterations = 1L << (maxDepth - depth + minDepth);
            Arena a((size_t(1) << (depth + 1)) - 1);
            long sum = 0;
            for (long j = 0; j < iterations; ++j) {
                a.reset();
                Node* t = make(depth, a);
                sum += check(t);
            }
            char buf[128];
            std::snprintf(buf, sizeof(buf), "%ld\t trees of depth %d\t check: %ld\n",
                          iterations, depth, sum);
            results[i] = buf;
        }
    };

    unsigned hw = std::thread::hardware_concurrency();
    if (hw == 0) hw = 4;
    unsigned nthreads = std::min<unsigned>(hw, (unsigned)numDepths);
    if (nthreads == 0) nthreads = 1;
    std::vector<std::thread> threads;
    for (unsigned t = 0; t < nthreads; ++t) threads.emplace_back(worker);
    for (auto& th : threads) th.join();

    for (int i = 0; i < numDepths; ++i) std::fputs(results[i].c_str(), stdout);

    std::printf("long lived tree of depth %d\t check: %ld\n", maxDepth, check(longLived));
    return 0;
}

